// If we've reached a restart point, reset the last_key and record the offset
    if (*counter == restart_interval) {
        restarts->push_back(static_cast<uint32_t>(buffer->size()));
        *last_key = "";
        *counter = 0;
    }

    // Compute the shared prefix length between the current key and last_key
    size_t shared = 0;
    if (!last_key->empty()) {
        while (shared < key.size() && shared < last_key->size() &&
               (*last_key)[shared] == key[shared]) {
            shared++;
        }
    }

    // Compute the non-shared part of the key
    const size_t non_shared = key.size() - shared;

    // Append the compressed key-value entry to the buffer
    // Format: shared_bytes (varint) | non_shared_bytes (varint) | value_bytes (varint) | key_delta | value
    std::string encoded;
    PutVarint32(&encoded, static_cast<uint32_t>(shared));
    PutVarint32(&encoded, static_cast<uint32_t>(non_shared));
    PutVarint32(&encoded, static_cast<uint32_t>(value.size()));
    encoded.append(key.data() + shared, non_shared);
    encoded.append(value.data(), value.size());

    buffer->append(encoded);

    // Update last_key to the current key
    *last_key = key.ToString();

    // Increment the entry counter
    (*counter)++;
// END_CODE

